<?php require 'includes/functions.php';$pageTitle='Shopping Bag';if(post()){verify_csrf();$id=number('product_id');$action=textval('action');if($action==='remove'){unset($_SESSION['cart'][$id]);flash('Item removed.');}elseif(in_array($action,['add','update'],true)){$p=query('SELECT * FROM products WHERE id=?',[$id])->fetch();$qty=textval('quantity')===''?1:number('quantity');$desired=$action==='add'?($_SESSION['cart'][$id]??0)+$qty:$qty;if(!$p||!available($p)){flash('This fragrance is currently sold out or unavailable.');}elseif($qty<1||$desired>min(99,$p['stock'])){flash('Choose a quantity between 1 and the available stock (maximum 99).');}else{$_SESSION['cart'][$id]=$desired;flash('Your bag has been updated.');}}redirect('cart.php');}$items=cart_items();$total=totals($items);require 'includes/header.php';?><section class="container section"><span class="eyebrow">YOUR SELECTION</span><h1>Shopping Bag</h1><?php if(!$items):?><div class="empty"><h2>Your bag is waiting.</h2><a class="button" href="<?=e(url('new-arrivals.php'))?>">Explore fragrances</a></div><?php else:?><div class="checkout-grid"><div><?php foreach($items as $p):?><article class="cart-item panel"><a href="<?=e(url('product.php?id='.$p['id']))?>"><img src="<?=e(url($p['image']?:'images/placeholder.svg'))?>" alt="<?=e($p['name'])?>"></a><div><h3><?=e($p['brand'].' '.$p['name'])?></h3><p><?=money($p['price'])?> each</p><?php if(!available($p)||$p['quantity']>$p['stock']):?><p class="out">Stock changed. Update or remove this item before checkout.</p><?php endif;?><form method="post" class="inline-form"><?php csrf();?><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Quantity<input type="number" name="quantity" min="1" max="99" value="<?=$p['quantity']?>" required></label><button name="action" value="update" class="outline">Update</button><button name="action" value="remove" class="link" formnovalidate>Remove</button></form></div><b><?=money($p['price']*$p['quantity'])?></b></article><?php endforeach;?></div><aside class="panel summary"><h2>Your total</h2><div>Subtotal <b><?=money($total['subtotal'])?></b></div><div>Delivery <b><?=money($total['shipping'])?></b></div><div class="total">Total <b><?=money($total['total'])?></b></div><p class="muted small">Cash on delivery. Free delivery from USD 50.</p><a class="button full" href="<?=e(url('checkout.php'))?>">Continue to checkout</a></aside></div><?php endif;?></section><?php require 'includes/footer.php';?>
